	[TerritoryId],
	[TerritoryIdName],
	[FirstName],
	[MiddleName],
	[LastName],
	[FullName],
	[Title],
	[JobTitle],
	[DomainName],
	[IsDisabled],
	[IsActiveDirectoryUser],
	[salutation],
	[internalemailaddress],
